import { useState, useEffect } from 'react'
import { supabase } from '../utils/supabase'
import { Calendar, Upload, Trash2, FileSpreadsheet, Edit2, X } from 'lucide-react'
import * as XLSX from 'xlsx'

interface DayOff {
  id: number
  employee_id: number
  employee_name: string
  day_off_date: string
  reason?: string
}

interface Employee {
  id: number
  employee_name: string
}

interface GroupedDayOff {
  date: string
  employees: Array<{ id: number; name: string; recordId: number }>
  isWeekend: boolean
}

export default function DaysOffPage() {
  const [employees, setEmployees] = useState<Employee[]>([])
  const [daysOff, setDaysOff] = useState<DayOff[]>([])
  const [selectedMonth, setSelectedMonth] = useState<string>('2026-04')
  const [selectedEmployee, setSelectedEmployee] = useState<string>('all')
  const [isUploading, setIsUploading] = useState(false)
  const [message, setMessage] = useState('')
  const [editingDay, setEditingDay] = useState<GroupedDayOff | null>(null)
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([])

  useEffect(() => {
    loadEmployees()
    loadAvailableEmployees()
  }, [])

  useEffect(() => {
    if (selectedMonth) {
      loadDaysOff()
    }
  }, [selectedMonth, selectedEmployee])

  async function loadEmployees() {
    const { data } = await supabase
      .from('employees')
      .select('id, employee_name')
      .eq('is_deleted', 'n')
      .order('employee_name')
    
    if (data) {
      setEmployees(data)
    }
  }

  async function loadAvailableEmployees() {
    const { data } = await supabase
      .from('employees')
      .select('id, employee_name')
      .eq('is_deleted', 'n')
      .order('employee_name')
    
    if (data) {
      setAvailableEmployees(data)
    }
  }

  async function loadDaysOff() {
    const [year, month] = selectedMonth.split('-').map(Number)
    const startDate = `${year}-${String(month).padStart(2, '0')}-01`
    const endDate = `${year}-${String(month + 1).padStart(2, '0')}-01`
    
    let query = supabase
      .from('employee_days_off_s_61f4962f_e')
      .select(`
        id,
        employee_id,
        day_off_date,
        reason,
        employees!inner(employee_name)
      `)
      .gte('day_off_date', startDate)
      .lt('day_off_date', endDate)
      .eq('is_deleted', 'n')
      .order('day_off_date')
    
    if (selectedEmployee !== 'all') {
      query = query.eq('employee_id', parseInt(selectedEmployee))
    }

    const { data, error } = await query
    
    if (error) {
      console.error('加载休息日失败:', error)
      return
    }

    const formattedData = data.map(item => ({
      id: item.id,
      employee_id: item.employee_id,
      employee_name: (item.employees as any).employee_name,
      day_off_date: item.day_off_date,
      reason: item.reason
    }))
    
    setDaysOff(formattedData)
  }

  function groupDaysOffByDate() {
    const grouped = new Map<string, GroupedDayOff>()
    
    daysOff.forEach(item => {
      if (!grouped.has(item.day_off_date)) {
        grouped.set(item.day_off_date, {
          date: item.day_off_date,
          employees: [],
          isWeekend: isWeekend(item.day_off_date)
        })
      }
      grouped.get(item.day_off_date)!.employees.push({
        id: item.employee_id,
        name: item.employee_name,
        recordId: item.id
      })
    })
    
    return Array.from(grouped.values()).sort((a, b) => a.date.localeCompare(b.date))
  }

  async function handleFileUpload(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]
    if (!file) return

    setIsUploading(true)
    setMessage('')

    try {
      const data = await file.arrayBuffer()
      const workbook = XLSX.read(data, { type: 'array', cellDates: true })
      
      if (workbook.SheetNames.length === 0) {
        setMessage('❌ Excel 文件中没有工作表')
        setIsUploading(false)
        return
      }

      const worksheet = workbook.Sheets[workbook.SheetNames[0]]
      const jsonData: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1 })
      
      if (jsonData.length < 2) {
        setMessage('❌ Excel 文件格式不正确，至少需要包含表头和数据行')
        setIsUploading(false)
        return
      }

      const expectedEmployees = ['周晅伊', '刘志文', '边宇', '孙培智', '李纯', '杨政阳', '杨雯喧']
      const headers = jsonData[0].map((h: any) => String(h || '').trim())
      
      if (headers.length < 2 || !headers[0].includes('日期')) {
        setMessage('❌ Excel 文件第一列必须为"日期姓名"列')
        setIsUploading(false)
        return
      }

      const actualEmployeeHeaders = headers.slice(1)
      const hasExpectedColumns = expectedEmployees.every(emp => 
        actualEmployeeHeaders.includes(emp)
      )

      if (!hasExpectedColumns) {
        setMessage(`❌ Excel 文件员工列不匹配。期望包含：${expectedEmployees.join('、')}`)
        setIsUploading(false)
        return
      }

      const records: Array<{ employee_id: number; day_off_date: string; reason?: string }> = []
      const errors: string[] = []

      for (let i = 1; i < jsonData.length; i++) {
        const row = jsonData[i]
        if (!row || row.length === 0) continue

        const dateValue = row[0]
        let formattedDate: string | null = null

        if (dateValue instanceof Date) {
          const year = dateValue.getFullYear()
          const month = String(dateValue.getMonth() + 1).padStart(2, '0')
          const day = String(dateValue.getDate()).padStart(2, '0')
          formattedDate = `${year}-${month}-${day}`
        } else if (typeof dateValue === 'string') {
          const dateStr = dateValue.trim()
          const match4Month = dateStr.match(/(\d{1,2}) 月 (\d{1,2}) 日/)
          if (match4Month) {
            const year = selectedMonth.split('-')[0]
            const month = String(match4Month[1]).padStart(2, '0')
            const day = String(match4Month[2]).padStart(2, '0')
            formattedDate = `${year}-${month}-${day}`
          } else {
            formattedDate = formatDate(dateStr)
          }
        }

        if (!formattedDate) {
          errors.push(`第${i + 1}行：日期格式不正确`)
          continue
        }

        for (let j = 1; j <= expectedEmployees.length && j < row.length; j++) {
          const cellValue = String(row[j] || '').trim().toLowerCase()
          const employeeName = expectedEmployees[j - 1]
          
          if (cellValue === '休' || cellValue === '休息') {
            const employee = employees.find(e => e.employee_name === employeeName)
            
            if (!employee) {
              errors.push(`第${i + 1}行：员工"${employeeName}"不存在于系统中`)
              continue
            }

            records.push({
              employee_id: employee.id,
              day_off_date: formattedDate,
              reason: '排班休息'
            })
          }
        }
      }

      if (errors.length > 0) {
        setMessage('⚠️ 部分数据导入失败：\n' + errors.join('\n'))
      }

      if (records.length === 0) {
        setMessage('❌ 没有有效的数据可导入（请确保在单元格中填写"休"）')
        setIsUploading(false)
        return
      }

      const { error: insertError } = await supabase
        .from('employee_days_off_s_61f4962f_e')
        .upsert(records, { onConflict: 'employee_id,day_off_date' })

      if (insertError) {
        setMessage('❌ 导入失败：' + insertError.message)
      } else {
        setMessage(`✅ 成功导入 ${records.length} 条休息日记录`)
        loadDaysOff()
      }
    } catch (err: any) {
      setMessage('❌ 读取文件失败：' + err.message)
    } finally {
      setIsUploading(false)
    }
  }

  function formatDate(dateStr: string): string | null {
    const formats = [
      /^(\d{4})-(\d{1,2})-(\d{1,2})$/,
      /^(\d{4})\/(\d{1,2})\/(\d{1,2})$/,
      /^(\d{1,2})-(\d{1,2})-(\d{4})$/,
      /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
    ]

    for (const format of formats) {
      const match = dateStr.match(format)
      if (match) {
        let year: number, month: number, day: number
        
        if (format.source.includes('d{4}') && match[1].length === 4) {
          year = parseInt(match[1])
          month = parseInt(match[2]) - 1
          day = parseInt(match[3])
        } else {
          day = parseInt(match[1])
          month = parseInt(match[2]) - 1
          year = parseInt(match[3])
        }

        const date = new Date(year, month, day)
        if (isNaN(date.getTime())) return null
        
        return `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`
      }
    }
    return null
  }

  async function addEmployeeToDay(date: string, employeeId: number) {
    const employee = availableEmployees.find(e => e.id === employeeId)
    if (!employee) return

    const { error } = await supabase
      .from('employee_days_off_s_61f4962f_e')
      .insert({
        employee_id: employee.id,
        day_off_date: date,
        reason: '排班休息'
      })

    if (error) {
      setMessage('❌ 添加失败：' + error.message)
    } else {
      setMessage(`✅ 已添加 ${employee.employee_name} 到 ${date} 的休息列表`)
      loadDaysOff()
      setEditingDay(null)
    }
  }

  async function removeEmployeeFromDay(recordId: number, employeeName: string) {
    if (!confirm(`确定要将 ${employeeName} 从休息列表中移除吗？`)) return

    const { error } = await supabase
      .from('employee_days_off_s_61f4962f_e')
      .update({ is_deleted: 'y' })
      .eq('id', recordId)

    if (error) {
      setMessage('❌ 移除失败：' + error.message)
    } else {
      setMessage(`✅ 已将 ${employeeName} 从休息列表中移除`)
      loadDaysOff()
      setEditingDay(null)
    }
  }

  function downloadTemplate() {
    const expectedEmployees = ['周晅伊', '刘志文', '边宇', '孙培智', '李纯', '杨政阳', '杨雯喧']
    
    const wb = XLSX.utils.book_new()
    
    const data = [
      ['日期姓名', ...expectedEmployees],
      ['4 月 1 日', '', '', '', '休', '', '', ''],
      ['4 月 2 日', '', '', '', '休', '', '', ''],
      ['4 月 3 日', '', '', '', '', '休', '', ''],
      ['4 月 4 日', '休', '', '休', '休', '', '', ''],
      ['4 月 5 日', '', '休', '', '', '', '休', ''],
    ]
    
    const ws = XLSX.utils.aoa_to_sheet(data)
    
    ws['!cols'] = [
      { wch: 12 },
      { wch: 10 },
      { wch: 10 },
      { wch: 10 },
      { wch: 10 },
      { wch: 10 },
      { wch: 10 },
      { wch: 10 },
    ]
    
    XLSX.utils.book_append_sheet(wb, ws, '休息日排班表')
    XLSX.writeFile(wb, '休息日排班模板.xlsx')
  }

  function getDayName(dateStr: string) {
    const date = new Date(dateStr)
    const names = ['日', '一', '二', '三', '四', '五', '六']
    return names[date.getDay()]
  }

  function isWeekend(dateStr: string) {
    const date = new Date(dateStr)
    const day = date.getDay()
    return day === 0 || day === 6
  }

  function getEmployeeColor(employeeName: string): string {
    const colorMap: Record<string, string> = {
      '周晅伊': 'bg-purple-100 text-purple-700',
      '刘志文': 'bg-blue-100 text-blue-700',
      '边宇': 'bg-green-100 text-green-700',
      '孙培智': 'bg-yellow-100 text-yellow-700',
      '李纯': 'bg-pink-100 text-pink-700',
      '杨政阳': 'bg-indigo-100 text-indigo-700',
      '杨雯喧': 'bg-orange-100 text-orange-700'
    }
    return colorMap[employeeName] || 'bg-gray-100 text-gray-700'
  }

  const groupedDaysOff = groupDaysOffByDate()

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold text-gray-800 mb-6">员工休息日管理</h1>

      <div className="bg-white rounded-lg shadow p-6 mb-6">
        <div className="flex flex-wrap gap-4 items-end">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">选择月份</label>
            <input
              type="month"
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">筛选员工</label>
            <select
              value={selectedEmployee}
              onChange={(e) => setSelectedEmployee(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">全部员工</option>
              {employees.map(emp => (
                <option key={emp.id} value={emp.id}>{emp.employee_name}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">导入 Excel</label>
            <label className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 cursor-pointer">
              <Upload className="w-4 h-4" />
              <span>上传文件</span>
              <input
                type="file"
                accept=".xlsx,.xls"
                onChange={handleFileUpload}
                className="hidden"
                disabled={isUploading}
              />
            </label>
          </div>

          <button
            onClick={downloadTemplate}
            className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center gap-2"
          >
            <FileSpreadsheet className="w-4 h-4" />
            下载模板
          </button>
        </div>

        {message && (
          <div className={`mt-4 p-3 rounded-lg ${message.startsWith('✅') ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'}`}>
            <pre className="whitespace-pre-wrap text-sm">{message}</pre>
          </div>
        )}

        <div className="mt-4 text-sm text-gray-600">
          <p>💡 提示：请严格按照模板格式填写</p>
          <ul className="list-disc list-inside text-xs text-gray-500 mt-1 space-y-1">
            <li><strong>第一列</strong>：日期姓名（日期格式：4 月 1 日、2026-04-01 等）</li>
            <li><strong>第二至八列</strong>：周晅伊、刘志文、边宇、孙培智、李纯、杨政阳、杨雯喧</li>
            <li><strong>单元格填写</strong>：在对应日期和员工的交叉单元格中填写"休"（不带标点符号）</li>
            <li><strong>空白单元格</strong>：表示当天上班，无需填写</li>
          </ul>
          <p className="text-xs text-gray-500 mt-2">支持 Excel 文件格式（.xlsx、.xls）</p>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow p-6">
        <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
          <Calendar className="w-5 h-5" />
          休息日列表（{selectedMonth}）
          <span className="text-sm text-gray-500 font-normal">共 {daysOff.length} 条记录</span>
        </h2>

        {daysOff.length === 0 ? (
          <div className="text-center py-12 text-gray-500">
            <Calendar className="w-16 h-16 mx-auto mb-4 opacity-30" />
            <p>本月暂无休息日记录</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">日期</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">星期</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">休息员工</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">人数</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">操作</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {groupedDaysOff.map((group, index) => (
                  <tr key={group.date} className={index % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                    <td className="px-4 py-3 text-sm font-medium text-gray-900">{group.date}</td>
                    <td className="px-4 py-3 text-sm">
                      <span className={`px-2 py-1 rounded text-xs font-medium ${group.isWeekend ? 'bg-orange-100 text-orange-700' : 'bg-purple-100 text-purple-800'}`}>
                        周{getDayName(group.date)}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-sm">
                      <div className="flex flex-wrap gap-1">
                        {group.employees.map(emp => (
                          <span key={emp.recordId} className={`px-2 py-1 rounded text-xs ${getEmployeeColor(emp.name)}`}>
                            {emp.name}
                          </span>
                        ))}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-700">
                      <span className="px-2 py-1 rounded bg-green-100 text-green-800 font-medium">
                        {group.employees.length} 人
                      </span>
                    </td>
                    <td className="px-4 py-3 text-sm">
                      <button
                        onClick={() => setEditingDay(group)}
                        className="text-blue-600 hover:text-blue-800 flex items-center gap-1 mr-3"
                      >
                        <Edit2 className="w-4 h-4" />
                        调整
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {editingDay && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold">
                调整休息员工 - {editingDay.date}
              </h3>
              <button
                onClick={() => setEditingDay(null)}
                className="text-gray-400 hover:text-gray-600"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            
            <div className="mb-4">
              <p className="text-sm text-gray-600 mb-2">当前休息员工：</p>
              <div className="space-y-2">
                {editingDay.employees.map(emp => (
                  <div key={emp.recordId} className="flex items-center justify-between p-2 bg-red-50 rounded">
                    <span className={`text-sm font-medium ${getEmployeeColor(emp.name).replace('bg-', 'text-').replace('-100', '-700')}`}>{emp.name}</span>
                    <button
                      onClick={() => removeEmployeeFromDay(emp.recordId, emp.name)}
                      className="text-red-600 hover:text-red-800 text-xs flex items-center gap-1"
                    >
                      <Trash2 className="w-3 h-3" />
                      移除
                    </button>
                  </div>
                ))}
              </div>
            </div>

            <div className="mb-6">
              <p className="text-sm text-gray-600 mb-2">添加休息员工：</p>
              <select
                onChange={(e) => {
                  const empId = parseInt(e.target.value)
                  if (empId) {
                    addEmployeeToDay(editingDay.date, empId)
                  }
                }}
                defaultValue=""
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              >
                <option value="">选择员工...</option>
                {availableEmployees
                  .filter(emp => !editingDay.employees.some(e => e.id === emp.id))
                  .map(emp => (
                    <option key={emp.id} value={emp.id}>
                      {emp.employee_name}
                    </option>
                  ))
                }
              </select>
            </div>
            
            <button
              onClick={() => setEditingDay(null)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
            >
              关闭
            </button>
          </div>
        </div>
      )}
    </div>
  )
}
