import { useEffect, useState, useRef } from 'react'
import { supabase } from '../utils/supabase'
import { Plus, Edit, Trash2, Upload, Download } from 'lucide-react'
import * as XLSX from 'xlsx'
import type { WorkStatisticsInsert, WorkStatisticsRow, EmployeesRow } from '@/types/database'

export default function WorkStatsPage() {
  const [workStats, setWorkStats] = useState<(WorkStatisticsRow & { employees?: any })[]>([])
  const [employees, setEmployees] = useState<EmployeesRow[]>([])
  const [showModal, setShowModal] = useState(false)
  const [editingRecord, setEditingRecord] = useState<WorkStatisticsRow | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [startDate, setStartDate] = useState<string>('')
  const [endDate, setEndDate] = useState<string>(new Date().toISOString().split('T')[0])
  const [filterEmployee, setFilterEmployee] = useState<string>('all')
  const [showImportModal, setShowImportModal] = useState(false)
  const [importPreview, setImportPreview] = useState<any[]>([])
  const [isImporting, setIsImporting] = useState(false)
  const [importProgress, setImportProgress] = useState('')
  const [shiftTypes, setShiftTypes] = useState<string[]>([])
  const topScrollRef = useRef<HTMLDivElement>(null)
  const tableScrollRef = useRef<HTMLDivElement>(null)

  function syncScroll(source: 'top' | 'table') {
    if (source === 'top' && topScrollRef.current && tableScrollRef.current) {
      tableScrollRef.current.scrollLeft = topScrollRef.current.scrollLeft
    } else if (source === 'table' && topScrollRef.current && tableScrollRef.current) {
      topScrollRef.current.scrollLeft = tableScrollRef.current.scrollLeft
    }
  }

  // Removed importFile state

  function parseExcelDate(excelDate: any): string {
    if (!excelDate) return new Date().toISOString().split('T')[0]
    if (typeof excelDate === 'number') {
      const date = new Date(Math.round((excelDate - 25569) * 86400 * 1000))
      return date.toISOString().split('T')[0]
    }
    const dateStr = String(excelDate)
    if (dateStr.includes('T')) return dateStr.split('T')[0]
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return dateStr
    const date = new Date(dateStr)
    if (!isNaN(date.getTime())) return date.toISOString().split('T')[0]
    return new Date().toISOString().split('T')[0]
  }

  function downloadTemplate() {
    const templateData = [
      {
        '员工姓名': '张三',
        '日期': new Date().toISOString().split('T')[0],
        '当天排班': '早班',
        '平台消息回复量': 100,
        '处理量': 50,
        '挽单量': 10,
        '处理订单金额': 5000,
        '挽单订单金额': 1000
      },
      {
        '员工姓名': '李四',
        '日期': new Date().toISOString().split('T')[0],
        '当天排班': '晚班',
        '平台消息回复量': 120,
        '处理量': 60,
        '挽单量': 15,
        '处理订单金额': 6000,
        '挽单订单金额': 1500
      }
    ]

    const worksheet = XLSX.utils.json_to_sheet(templateData)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, '工作量统计')

    const colWidths = [
      { wch: 12 },
      { wch: 12 },
      { wch: 10 },
      { wch: 16 },
      { wch: 10 },
      { wch: 10 },
      { wch: 14 },
      { wch: 14 }
    ]
    worksheet['!cols'] = colWidths

    XLSX.writeFile(workbook, `工作量统计导入模版_${new Date().toISOString().split('T')[0]}.xlsx`)
  }

  function exportData() {
    if (filteredStats.length === 0) {
      alert('没有数据可导出')
      return
    }

    const exportRows = filteredStats.map(record => {
      const processCount = record.order_followup_count || 0
      const saveCount = record.save_order_count || 0
      
      return {
        '员工姓名': (record.employees as any)?.employee_name || '-',
        '日期': record.work_date,
        '当天排班': record.shift_type || '-',
        '平台消息回复量': record.platform_message_count || 0,
        '处理量': processCount,
        '挽单量': saveCount,
        '处理订单金额': record.processed_order_amount || 0,
        '挽单订单金额': record.saved_order_amount || 0
      }
    })

    const worksheet = XLSX.utils.json_to_sheet(exportRows)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, '工作量统计')

    const colWidths = [
      { wch: 12 },
      { wch: 12 },
      { wch: 10 },
      { wch: 16 },
      { wch: 10 },
      { wch: 10 },
      { wch: 14 },
      { wch: 14 }
    ]
    worksheet['!cols'] = colWidths

    const dateRange = startDate && endDate 
      ? `${startDate}_${endDate}` 
      : new Date().toISOString().split('T')[0]
    XLSX.writeFile(workbook, `工作量统计导出_${dateRange}.xlsx`)
  }

  const [formData, setFormData] = useState({
    employee_id: '',
    work_date: new Date().toISOString().split('T')[0],
    shift_type: '',
    platform_message_count: '',
    order_followup_count: '',
    save_order_count: '',
    processed_order_amount: '',
    saved_order_amount: ''
  })

  useEffect(() => {
    loadEmployees()
    loadWorkStats()
    loadShiftTypes()
  }, [startDate, endDate, filterEmployee])

  async function loadShiftTypes() {
    const { data, error } = await supabase
      .from('work_statistics')
      .select('shift_type')
      .not('shift_type', 'is', null)
    
    if (error) {
      console.error('Failed to load shift types:', error)
      return
    }
    
    const uniqueShifts = [...new Set(data.map(r => r.shift_type).filter(Boolean))] as string[]
    uniqueShifts.sort()
    setShiftTypes(uniqueShifts)
  }

  async function loadEmployees() {
    const { data, error } = await supabase
      .from('employees')
      .select('*')
      .eq('is_deleted', 'n')
      .order('employee_name')
    if (error) throw error
    setEmployees(data || [])
    if (data && data.length > 0 && !formData.employee_id) {
      setFormData(prev => ({ ...prev, employee_id: String(data[0].id) }))
    }
  }

  async function loadWorkStats() {
    try {
      const { data: employeesData } = await supabase
        .from('employees')
        .select('*')
        .eq('is_deleted', 'n')

      let statsQuery = supabase
        .from('work_statistics')
        .select('*')
        .eq('is_deleted', 'n')
      
      // 如果选择了开始日期和结束日期，则按日期范围筛选
      if (startDate && endDate) {
        statsQuery = statsQuery.gte('work_date', startDate).lte('work_date', endDate)
      } else if (startDate) {
        statsQuery = statsQuery.gte('work_date', startDate)
      } else if (endDate) {
        statsQuery = statsQuery.lte('work_date', endDate)
      }
      
      // 如果选择了特定员工，则筛选该员工的数据
      if (filterEmployee !== 'all') {
        const selectedEmp = employeesData?.find(e => e.employee_name === filterEmployee)
        if (selectedEmp) {
          statsQuery = statsQuery.eq('emp_id', selectedEmp.id)
        }
      }
      
      const { data, error } = await statsQuery.order('work_date', { ascending: false })

      if (error) throw error
      
      const enrichedData = (data || []).map(record => {
        const employee = employeesData?.find(e => String(e.id) === String(record.emp_id))
        return { ...record, employees: employee || null }
      })
      
      setWorkStats(enrichedData)
    } catch (err: any) {
      console.error('加载失败:', err)
      alert('加载数据失败：' + err.message)
    }
  }

  function openAddModal() {
    setEditingRecord(null)
    setFormData({
      employee_id: employees[0]?.id ? String(employees[0].id) : '',
      work_date: new Date().toISOString().split('T')[0],
      shift_type: '',
      platform_message_count: '',
      order_followup_count: '',
      save_order_count: '',
      processed_order_amount: '',
      saved_order_amount: ''
    })
    setShowModal(true)
  }

  function openEditModal(record: WorkStatisticsRow) {
    setEditingRecord(record)
    setFormData({
      employee_id: record.emp_id || '',
      work_date: record.work_date,
      shift_type: record.shift_type || '',
      platform_message_count: String(record.platform_message_count || ''),
      order_followup_count: String(record.order_followup_count || ''),
      save_order_count: String(record.save_order_count || ''),
      processed_order_amount: String(record.processed_order_amount || ''),
      saved_order_amount: String(record.saved_order_amount || '')
    })
    setShowModal(true)
  }

  async function handleSubmit() {
    try {
      const submitData = {
        emp_id: formData.employee_id,
        work_date: formData.work_date,
        shift_type: formData.shift_type,
        platform_message_count: parseInt(formData.platform_message_count) || 0,
        order_followup_count: parseInt(formData.order_followup_count) || 0,
        save_order_count: parseInt(formData.save_order_count) || 0,
        processed_order_amount: parseFloat(formData.processed_order_amount) || 0,
        saved_order_amount: parseFloat(formData.saved_order_amount) || 0,
        is_deleted: 'n'
      }

      if (editingRecord) {
        await supabase
          .from('work_statistics')
          .update(submitData)
          .eq('id', editingRecord.id)
      } else {
        await supabase
          .from('work_statistics')
          .insert([submitData])
      }

      alert(editingRecord ? '更新成功' : '添加成功')
      setShowModal(false)
      loadWorkStats()
    } catch (err: any) {
      console.error('提交失败:', err)
      alert('操作失败：' + err.message)
    }
  }

  async function handleDelete(id: number) {
    if (!confirm('确定要删除这条记录吗？')) return
    
    try {
      await supabase
        .from('work_statistics')
        .update({ is_deleted: 'y' })
        .eq('id', id)
      
      alert('删除成功')
      loadWorkStats()
    } catch (err: any) {
      console.error('删除失败:', err)
      alert('删除失败：' + err.message)
    }
  }

  function handleFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    
    const reader = new FileReader()
    reader.onload = (event) => {
      const data = new Uint8Array(event.target?.result as ArrayBuffer)
      const workbook = XLSX.read(data, { type: 'array' })
      const sheetName = workbook.SheetNames[0]
      const worksheet = workbook.Sheets[sheetName]
      const jsonData = XLSX.utils.sheet_to_json(worksheet)
      setImportPreview(jsonData)
    }
    reader.readAsArrayBuffer(file)
  }

  async function processImport() {
    if (!importPreview.length) {
      alert('请先选择文件')
      return
    }

    setIsImporting(true)
    setImportProgress('正在处理数据...')

    try {
      // 构建员工姓名到 ID 的映射，加速查找
      const employeeMap = new Map<string, string>()
      employees.forEach(e => {
        employeeMap.set(e.employee_name, String(e.id))
      })

      const records: WorkStatisticsInsert[] = []
      const failReasons: string[] = []
      const seenRecords = new Set<string>()

      for (let i = 0; i < importPreview.length; i++) {
        const row = importPreview[i]
        const empName = row['员工姓名']
        if (!empName) {
          failReasons.push(`第${i + 1}行：缺少员工姓名`)
          continue
        }

        const empId = employeeMap.get(empName)
        if (!empId) {
          failReasons.push(`第${i + 1}行：未找到员工 "${empName}"，请先在员工管理中添加`)
          continue
        }

        const workDate = parseExcelDate(row['日期'])
        const shiftType = row['当天排班'] || null
        
        // 只根据 emp_id + work_date 判断是否重复，不管排班类型
        // 这样即使同一天都是"休"，也只会保留最后一条（用于统计 0 消息量）
        const uniqueKey = `${empId}-${workDate}`
        if (seenRecords.has(uniqueKey)) {
          // 不是错误，只是跳过，因为后面会统一去重
          continue
        }
        seenRecords.add(uniqueKey)

        const record: WorkStatisticsInsert = {
          emp_id: empId,
          employee_id: null,
          work_date: workDate,
          shift_type: shiftType,
          platform_message_count: parseInt(row['平台消息回复量']) || 0,
          save_order_count: parseInt(row['挽单量'] || row['挽单量（工单登记量）']) || 0,
          order_followup_count: parseInt(row['处理量'] || row['订单跟进量'] || row['订单跟进量（售后单）']) || 0,
          processed_order_amount: parseFloat(row['处理订单金额'] || row['处理金额']) || 0,
          saved_order_amount: parseFloat(row['挽单订单金额'] || row['挽单金额']) || 0
        }

        records.push(record)
        
        if ((i + 1) % 100 === 0) {
          setImportProgress(`已处理 ${i + 1}/${importPreview.length} 条记录...`)
          // 让出主线程，避免 UI 阻塞
          await new Promise(resolve => setTimeout(resolve, 0))
        }
      }

      const failCount = failReasons.length
      setImportProgress(`处理完成，共 ${records.length} 条有效记录，${failCount} 条失败`)

      if (records.length === 0) {
        const errorMsg = failReasons.length > 0 
          ? `导入失败：\n${failReasons.slice(0, 10).join('\n')}${failReasons.length > 10 ? `\n...等${failReasons.length - 10}条错误` : ''}`
          : '没有有效的数据可导入'
        alert(errorMsg)
        setIsImporting(false)
        return
      }

      // 批量删除旧数据 - 按员工分组批量删除
      setImportProgress('正在清理旧数据...')
      const recordsByEmp = new Map<string, string[]>()
      records.forEach(r => {
        if (!recordsByEmp.has(r.emp_id!)) {
          recordsByEmp.set(r.emp_id!, [])
        }
        recordsByEmp.get(r.emp_id!)!.push(r.work_date)
      })

      // 按员工批量删除（每个员工一次删除请求）
      for (const [empId, dates] of recordsByEmp.entries()) {
        const { error: deleteError } = await supabase
          .from('work_statistics')
          .delete()
          .eq('emp_id', empId)
          .in('work_date', dates)
        
        if (deleteError) {
          console.error('删除失败:', deleteError)
          throw new Error(`删除旧数据失败：${deleteError.message}`)
        }
      }

      // 按 emp_id + work_date 分组，确保每个组合只保留最后一条记录
      // 注意：即使排班是"休"、消息量为 0，也需要保留用于统计
      const uniqueRecords = new Map<string, WorkStatisticsInsert>()
      records.forEach(r => {
        const key = `${r.emp_id}|${r.work_date}`
        uniqueRecords.set(key, r) // 后面的会覆盖前面的，保证使用最新数据
      })
      
      const finalRecords = Array.from(uniqueRecords.values())

      // 批量插入新数据 - 使用 upsert 策略处理冲突
      setImportProgress('正在导入数据...')
      
      // 分批次插入，每批 100 条，避免单次请求过大
      const batchSize = 100
      let totalInserted = 0
      
      for (let i = 0; i < finalRecords.length; i += batchSize) {
        const batch = finalRecords.slice(i, i + batchSize)
        
        // 使用 INSERT ... ON CONFLICT DO UPDATE 语法
        const { error: insertError, data: insertedData } = await supabase
          .from('work_statistics')
          .upsert(batch, { 
            onConflict: 'emp_id,work_date',
            ignoreDuplicates: false  // false = 冲突时更新，true = 冲突时忽略
          })
          .select()
        
        if (insertError) {
          console.error('批量插入失败:', insertError)
          throw new Error(`插入失败：${insertError.message}`)
        }
        
        totalInserted += insertedData?.length || 0
        setImportProgress(`正在导入数据... ${totalInserted}/${finalRecords.length}`)
        
        // 短暂延迟，避免请求过快
        await new Promise(resolve => setTimeout(resolve, 50))
      }
      
      const data = finalRecords // 使用原始 records 作为 data
      const error = null

      if (error) {
        console.error('插入失败:', error)
        throw error
      }
      
      const insertedCount = Array.isArray(data) ? data.length : records.length
      
      const message = failCount > 0
        ? `成功导入 ${insertedCount} 条记录\n${failReasons.slice(0, 5).join('\n')}${failReasons.length > 5 ? `\n...等${failReasons.length - 5}条错误` : ''}`
        : `成功导入 ${insertedCount} 条记录`
      
      alert(message)
      setShowImportModal(false)
      setImportPreview([])
      loadWorkStats()
    } catch (err: any) {
      console.error('导入异常:', err)
      alert('导入失败：' + err.message)
    } finally {
      setIsImporting(false)
    }
  }

  const filteredStats = workStats.filter(record => {
    const searchLower = searchTerm.toLowerCase()
    return (
      (record.employees as any)?.employee_name?.toLowerCase().includes(searchLower) ||
      (record.employees as any)?.department?.toLowerCase().includes(searchLower) ||
      (record.shift_type || '').toLowerCase().includes(searchLower)
    )
  })

  return (
    <div className="p-6">
      <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-6">
        <h1 className="text-2xl font-bold text-gray-800">工作量统计</h1>
        <div className="flex flex-wrap items-center gap-3">
          <select
            value={filterEmployee}
            onChange={(e) => setFilterEmployee(e.target.value)}
            className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white"
          >
            <option value="all">全部员工</option>
            {employees.map(emp => (
              <option key={emp.id} value={emp.employee_name}>{emp.employee_name}</option>
            ))}
          </select>
          <div className="flex items-center gap-2">
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              placeholder="开始日期"
              className="px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
            />
            <span className="text-gray-500">-</span>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              placeholder="结束日期"
              className="px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
            />
          </div>
          <button
            onClick={() => {
              setStartDate('')
              setEndDate(new Date().toISOString().split('T')[0])
            }}
            className="px-3 py-2 text-sm text-gray-600 hover:text-gray-800"
          >
            重置
          </button>
          <button
            onClick={downloadTemplate}
            className="flex items-center gap-2 px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
          >
            <Download className="w-4 h-4" />
            下载模版
          </button>
          <button
            onClick={exportData}
            className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
          >
            <Download className="w-4 h-4" />
            导出数据
          </button>
          <button
            onClick={() => setShowImportModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
          >
            <Upload className="w-4 h-4" />
            导入数据
          </button>
          <button
            onClick={openAddModal}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            <Plus className="w-4 h-4" />
            添加记录
          </button>
        </div>
      </div>

      <div className="mb-6 flex gap-3">
        <input
          type="text"
          placeholder="搜索员工、部门、排班..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
        />
      </div>

      <div className="bg-white rounded-lg shadow overflow-hidden">
        <div 
          ref={topScrollRef}
          onScroll={() => syncScroll('top')}
          className="overflow-x-auto scrollbar-thin"
          style={{ height: '12px' }}
        >
          <div style={{ width: '1200px', height: '1px' }}></div>
        </div>
        <div 
          ref={tableScrollRef}
          onScroll={() => syncScroll('table')}
          className="overflow-x-auto"
        >
          <table className="min-w-full divide-y divide-gray-200 whitespace-nowrap" style={{ minWidth: '1200px' }}>
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase sticky left-0 bg-gray-50 z-10">日期</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">员工</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">部门</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">排班</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">消息回复量</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">处理量</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">挽单量</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase min-w-[120px]">处理金额</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase min-w-[120px]">挽单金额</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase sticky right-0 bg-gray-50 z-10 min-w-[80px]">操作</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {filteredStats.map((record) => (
                <tr key={record.id} className="hover:bg-gray-50">
                  <td className="px-4 py-4 text-sm text-gray-900 sticky left-0 bg-white z-10">{record.work_date}</td>
                  <td className="px-4 py-4 text-sm text-gray-900">
                    {(record.employees as any)?.employee_name || '-'}
                  </td>
                  <td className="px-4 py-4 text-sm text-gray-500">
                    {(record.employees as any)?.department || '-'}
                  </td>
                  <td className="px-4 py-4 text-sm text-gray-500">{record.shift_type || '-'}</td>
                  <td className="px-4 py-4 text-sm font-medium text-blue-600">{record.platform_message_count}</td>
                  <td className="px-4 py-4 text-sm font-medium text-amber-600">{record.order_followup_count || '-'}</td>
                  <td className="px-4 py-4 text-sm font-medium text-purple-600">{record.save_order_count}</td>
                  <td className="px-4 py-4 text-sm font-medium text-green-600">₩{(record.processed_order_amount || 0).toLocaleString()}</td>
                  <td className="px-4 py-4 text-sm font-medium text-orange-600">₩{(record.saved_order_amount || 0).toLocaleString()}</td>
                  <td className="px-4 py-4 text-sm font-medium sticky right-0 bg-white z-10">
                    <button onClick={() => openEditModal(record)} className="text-blue-600 hover:text-blue-900 mr-3">
                      <Edit className="w-4 h-4" />
                    </button>
                    <button onClick={() => handleDelete(record.id)} className="text-red-600 hover:text-red-900">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {filteredStats.length === 0 && (
          <div className="text-center py-12 text-gray-500">暂无数据</div>
        )}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">{editingRecord ? '编辑记录' : '添加记录'}</h2>
            
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">员工</label>
                <select
                  value={formData.employee_id}
                  onChange={(e) => setFormData(prev => ({ ...prev, employee_id: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  {employees.map(emp => (
                    <option key={emp.id} value={emp.id}>{emp.employee_name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">日期</label>
                <input
                  type="date"
                  value={formData.work_date}
                  onChange={(e) => setFormData(prev => ({ ...prev, work_date: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">排班类型</label>
                <select
                  value={formData.shift_type}
                  onChange={(e) => setFormData(prev => ({ ...prev, shift_type: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">请选择</option>
                  {shiftTypes.map(shift => (
                    <option key={shift} value={shift}>{shift}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">平台消息回复量</label>
                <input
                  type="number"
                  value={formData.platform_message_count}
                  onChange={(e) => setFormData(prev => ({ ...prev, platform_message_count: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">处理量</label>
                <input
                  type="number"
                  value={formData.order_followup_count}
                  onChange={(e) => setFormData(prev => ({ ...prev, order_followup_count: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">挽单量</label>
                <input
                  type="number"
                  value={formData.save_order_count}
                  onChange={(e) => setFormData(prev => ({ ...prev, save_order_count: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">处理订单金额（元）</label>
                <input
                  type="number"
                  step="0.01"
                  value={formData.processed_order_amount}
                  onChange={(e) => setFormData(prev => ({ ...prev, processed_order_amount: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="请输入处理订单金额"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">挽单订单金额（元）</label>
                <input
                  type="number"
                  step="0.01"
                  value={formData.saved_order_amount}
                  onChange={(e) => setFormData(prev => ({ ...prev, saved_order_amount: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="请输入挽单订单金额"
                />
              </div>
            </div>

            <div className="mt-6 flex justify-end gap-3">
              <button
                onClick={() => setShowModal(false)}
                className="px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200"
              >
                取消
              </button>
              <button
                onClick={handleSubmit}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                {editingRecord ? '更新' : '添加'}
              </button>
            </div>
          </div>
        </div>
      )}

      {showImportModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl">
            <h2 className="text-xl font-bold mb-4">导入数据</h2>
            
            <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
              <p className="text-sm font-medium text-blue-800 mb-2">导入格式说明：</p>
              <p className="text-sm text-blue-700">Excel 文件需包含以下列：员工姓名、日期、当天排班、平台消息回复量、处理量、挽单量、处理订单金额、挽单订单金额</p>
              <button
                onClick={downloadTemplate}
                className="mt-2 text-sm text-blue-600 hover:text-blue-800 underline"
              >
                点击下载导入模版
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">选择 Excel 文件</label>
                <input
                  type="file"
                  accept=".xlsx,.xls"
                  onChange={handleFileChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>

              {importPreview.length > 0 && (
                <div className="border rounded-lg p-4 bg-gray-50">
                  <p className="text-sm text-gray-600 mb-2">预览数据：{importPreview.length} 条</p>
                  <div className="max-h-60 overflow-auto">
                    <table className="min-w-full text-sm">
                      <thead>
                        <tr className="border-b">
                          <th className="text-left py-2">员工姓名</th>
                          <th className="text-left py-2">日期</th>
                          <th className="text-left py-2">排班</th>
                          <th className="text-left py-2">消息回复量</th>
                          <th className="text-left py-2">处理量</th>
                          <th className="text-left py-2">挽单量</th>
                          <th className="text-left py-2">处理金额</th>
                          <th className="text-left py-2">挽单金额</th>
                        </tr>
                      </thead>
                      <tbody>
                        {importPreview.slice(0, 5).map((row, idx) => {
                          const processCount = parseInt(row['处理量'] || row['订单跟进量'] || row['订单跟进量（售后单）']) || 0
                          const saveCount = parseInt(row['挽单量'] || row['挽单量（工单登记量）']) || 0
                          return (
                            <tr key={idx} className="border-b">
                              <td className="py-2">{row['员工姓名']}</td>
                              <td className="py-2">{row['日期']}</td>
                              <td className="py-2">{row['当天排班']}</td>
                              <td className="py-2">{row['平台消息回复量']}</td>
                              <td className="py-2">{processCount}</td>
                              <td className="py-2">{saveCount}</td>
                              <td className="py-2">{row['处理订单金额'] || row['处理金额'] || '-'}</td>
                              <td className="py-2">{row['挽单订单金额'] || row['挽单金额'] || '-'}</td>
                            </tr>
                          )
                        })}
                      </tbody>
                    </table>
                    {importPreview.length > 5 && (
                      <p className="text-sm text-gray-500 mt-2">... 还有 {importPreview.length - 5} 条</p>
                    )}
                  </div>
                </div>
              )}

              {importProgress && (
                <div className="mt-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                  <p className="text-sm text-blue-800">{importProgress}</p>
                </div>
              )}
            </div>

            <div className="mt-6 flex justify-end gap-3">
              <button
                onClick={() => {
                  setShowImportModal(false)
                  setImportPreview([])
                  setImportProgress('')
                }}
                className="px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200"
                disabled={isImporting}
              >
                取消
              </button>
              <button
                onClick={processImport}
                disabled={!importPreview.length || isImporting}
                className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50"
              >
                {isImporting ? '导入中...' : '开始导入'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
