import { useEffect, useState } from 'react'
import { supabase } from '../utils/supabase'
import { Plus, Edit, Trash2, Search, Users, Building2, Briefcase, UserCheck } from 'lucide-react'
import type { EmployeesRow } from '@/types/database'

const DEPARTMENT_COLORS: Record<string, { bg: string; text: string; border: string }> = {
  '运营部': { bg: 'bg-sky-200', text: 'text-sky-800', border: 'border-sky-400' },
  '客服部': { bg: 'bg-emerald-200', text: 'text-emerald-800', border: 'border-emerald-400' },
  '技术部': { bg: 'bg-violet-200', text: 'text-violet-800', border: 'border-violet-400' },
  '市场部': { bg: 'bg-amber-200', text: 'text-amber-800', border: 'border-amber-400' },
  '人事部': { bg: 'bg-rose-200', text: 'text-rose-800', border: 'border-rose-400' },
  '财务部': { bg: 'bg-teal-200', text: 'text-teal-800', border: 'border-teal-400' },
  'default': { bg: 'bg-slate-200', text: 'text-slate-800', border: 'border-slate-400' }
}

const POSITION_COLORS: Record<string, { bg: string; text: string }> = {
  '经理': { bg: 'bg-cyan-200', text: 'text-cyan-800' },
  '主管': { bg: 'bg-indigo-200', text: 'text-indigo-800' },
  '专员': { bg: 'bg-fuchsia-200', text: 'text-fuchsia-800' },
  '助理': { bg: 'bg-lime-200', text: 'text-lime-800' },
  'default': { bg: 'bg-slate-200', text: 'text-slate-800' }
}

function getDepartmentColor(dept: string | null) {
  if (!dept) return DEPARTMENT_COLORS.default
  return DEPARTMENT_COLORS[dept] || DEPARTMENT_COLORS.default
}

function getPositionColor(position: string | null) {
  if (!position) return POSITION_COLORS.default
  for (const [key, value] of Object.entries(POSITION_COLORS)) {
    if (position.includes(key)) return value
  }
  return POSITION_COLORS.default
}

export default function EmployeePage() {
  const [employees, setEmployees] = useState<EmployeesRow[]>([])
  const [loading, setLoading] = useState(true)
  const [showModal, setShowModal] = useState(false)
  const [editingEmployee, setEditingEmployee] = useState<EmployeesRow | null>(null)
  const [searchTerm, setSearchTerm] = useState('')

  const [formData, setFormData] = useState({
    employee_name: '',
    department: '',
    position: ''
  })

  useEffect(() => {
    loadEmployees()
  }, [])

  async function loadEmployees() {
    try {
      const { data, error } = await supabase
        .from('employees')
        .select('*')
        .eq('is_deleted', 'n')
        .order('created_at', { ascending: false })

      if (error) throw error
      setEmployees(data || [])
    } catch (error) {
      console.error('加载员工列表失败:', error)
    } finally {
      setLoading(false)
    }
  }

  function openModal(employee?: EmployeesRow) {
    if (employee) {
      setEditingEmployee(employee)
      setFormData({
        employee_name: employee.employee_name,
        department: employee.department || '',
        position: employee.position || ''
      })
    } else {
      setEditingEmployee(null)
      setFormData({
        employee_name: '',
        department: '',
        position: ''
      })
    }
    setShowModal(true)
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    
    try {
      if (editingEmployee) {
        const updateData: any = { ...formData }
        // 如果编辑时 emp_id 为空，生成一个新的
        if (!editingEmployee.emp_id) {
          const generatedUuid = crypto.randomUUID()
          updateData.emp_id = generatedUuid
        }
        
        const { error } = await supabase
          .from('employees')
          .update(updateData)
          .eq('id', editingEmployee.id)

        if (error) throw error
      } else {
        // 生成 UUID 作为 emp_id
        const generatedUuid = crypto.randomUUID()
        const { error } = await supabase
          .from('employees')
          .insert([{ ...formData, emp_id: generatedUuid }])

        if (error) throw error
      }

      setShowModal(false)
      loadEmployees()
    } catch (error: any) {
      if (error.code === '42501' || error.status === 403) {
        alert('您没有权限执行此操作')
        return
      }
      alert('操作失败：' + error.message)
    }
  }

  async function handleBatchFix() {
    if (!confirm('确定要为所有缺少 emp_id 的员工生成 UUID 吗？\n\n此操作将自动为每个员工分配一个唯一的 ID。')) return

    try {
      const employeesWithoutEmpId = employees.filter(e => !e.emp_id)
      
      if (employeesWithoutEmpId.length === 0) {
        alert('所有员工已有有效的 emp_id，无需修复')
        return
      }

      let successCount = 0
      for (const emp of employeesWithoutEmpId) {
        const generatedUuid = crypto.randomUUID()
        const { error } = await supabase
          .from('employees')
          .update({ emp_id: generatedUuid })
          .eq('id', emp.id)

        if (!error) successCount++
      }

      alert(`批量修复完成！\n成功修复 ${successCount}/${employeesWithoutEmpId.length} 个员工`)
      loadEmployees()
    } catch (error: any) {
      alert('批量修复失败：' + error.message)
    }
  }

  async function handleDelete(id: number) {
    if (!confirm('确定要删除该员工吗？')) return

    try {
      const { error } = await supabase
        .from('employees')
        .update({ is_deleted: 'y' })
        .eq('id', id)

      if (error) throw error
      loadEmployees()
    } catch (error: any) {
      if (error.code === '42501' || error.status === 403) {
        alert('您没有权限执行此操作')
        return
      }
      alert('删除失败：' + error.message)
    }
  }

  const filteredEmployees = employees.filter(emp =>
    emp.employee_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.department?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.position?.toLowerCase().includes(searchTerm.toLowerCase())
  )

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-900">员工管理</h2>
        <div className="flex gap-2">
          <button
            onClick={handleBatchFix}
            className="flex items-center px-4 py-2 bg-gradient-to-r from-amber-400 to-orange-400 text-amber-900 rounded-lg hover:from-amber-500 hover:to-orange-500 shadow-sm hover:shadow-md transition-all border border-amber-400"
          >
            批量修复 emp_id
          </button>
          <button
            onClick={() => openModal()}
            className="flex items-center px-4 py-2 bg-[#0089FF] text-white rounded-lg hover:bg-[#0077E6] shadow-sm hover:shadow-md transition-all"
          >
            <Plus className="w-4 h-4 mr-2" />
            添加员工
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-gradient-to-br from-sky-300 to-sky-400 rounded-xl p-5 text-sky-900 shadow-md border border-sky-400">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sky-800 text-sm">员工总数</p>
              <p className="text-3xl font-bold mt-1">{employees.length}</p>
            </div>
            <div className="bg-white/60 p-3 rounded-lg">
              <Users className="w-6 h-6 text-sky-700" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-rose-300 to-rose-400 rounded-xl p-5 text-rose-900 shadow-md border border-rose-400">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-rose-800 text-sm">部门数量</p>
              <p className="text-3xl font-bold mt-1">{new Set(employees.map(e => e.department).filter(Boolean)).size}</p>
            </div>
            <div className="bg-white/60 p-3 rounded-lg">
              <Building2 className="w-6 h-6 text-rose-700" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-violet-300 to-violet-400 rounded-xl p-5 text-violet-900 shadow-md border border-violet-400">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-violet-800 text-sm">职位类型</p>
              <p className="text-3xl font-bold mt-1">{new Set(employees.map(e => e.position).filter(Boolean)).size}</p>
            </div>
            <div className="bg-white/60 p-3 rounded-lg">
              <Briefcase className="w-6 h-6 text-violet-700" />
            </div>
          </div>
        </div>
        <div className="bg-gradient-to-br from-teal-300 to-teal-400 rounded-xl p-5 text-teal-900 shadow-md border border-teal-400">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-teal-800 text-sm">已配置ID</p>
              <p className="text-3xl font-bold mt-1">{employees.filter(e => e.emp_id).length}</p>
            </div>
            <div className="bg-white/60 p-3 rounded-lg">
              <UserCheck className="w-6 h-6 text-teal-700" />
            </div>
          </div>
        </div>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
        <input
          type="text"
          placeholder="搜索员工姓名、部门、职位..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white shadow-sm"
        />
      </div>

      {loading ? (
        <div className="flex justify-center items-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent"></div>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-gray-100">
          <table className="min-w-full divide-y divide-gray-100">
            <thead>
              <tr className="bg-gradient-to-r from-slate-50 to-gray-50">
                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">姓名</th>
                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">部门</th>
                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">职位</th>
                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">emp_id 状态</th>
                <th className="px-6 py-4 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">创建时间</th>
                <th className="px-6 py-4 text-right text-xs font-semibold text-gray-600 uppercase tracking-wider">操作</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-50">
              {filteredEmployees.map((employee, idx) => {
                const deptColor = getDepartmentColor(employee.department)
                const posColor = getPositionColor(employee.position)
                return (
                <tr key={employee.id} className={`hover:bg-blue-50/50 transition-colors ${idx % 2 === 0 ? 'bg-white' : 'bg-gray-50/30'}`}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className="w-8 h-8 rounded-full bg-[#0089FF] flex items-center justify-center text-white text-sm font-medium mr-3">
                        {employee.employee_name.charAt(0)}
                      </div>
                      <span className="text-sm font-medium text-gray-900">{employee.employee_name}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {employee.department ? (
                      <span className={`px-3 py-1 rounded-full text-xs font-medium border ${deptColor.bg} ${deptColor.text} ${deptColor.border}`}>
                        {employee.department}
                      </span>
                    ) : (
                      <span className="text-gray-400 text-sm">-</span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {employee.position ? (
                      <span className={`px-3 py-1 rounded-full text-xs font-medium ${posColor.bg} ${posColor.text}`}>
                        {employee.position}
                      </span>
                    ) : (
                      <span className="text-gray-400 text-sm">-</span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {employee.emp_id ? (
                      <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-emerald-200 text-emerald-800 border border-emerald-400">
                        <span className="w-1.5 h-1.5 bg-emerald-600 rounded-full mr-1.5"></span>
                        已配置
                      </span>
                    ) : (
                      <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-rose-200 text-rose-800 border border-rose-400">
                        <span className="w-1.5 h-1.5 bg-rose-600 rounded-full mr-1.5"></span>
                        缺失
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {new Date(employee.created_at!).toLocaleDateString('zh-CN')}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right">
                    <button
                      onClick={() => openModal(employee)}
                      className="p-2 text-sky-700 hover:text-white hover:bg-sky-500 rounded-lg transition-all mr-1"
                    >
                      <Edit className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDelete(employee.id)}
                      className="p-2 text-rose-700 hover:text-white hover:bg-rose-500 rounded-lg transition-all"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              )})}
            </tbody>
          </table>
          {filteredEmployees.length === 0 && (
            <div className="text-center py-16 text-gray-400">
              <Users className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p>暂无数据</p>
            </div>
          )}
        </div>
      )}

      {showModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl border border-gray-100">
            <h3 className="text-xl font-bold mb-6 text-gray-800 flex items-center">
              <span className={`w-8 h-8 rounded-lg flex items-center justify-center mr-3 ${editingEmployee ? 'bg-gradient-to-br from-amber-400 to-orange-400' : 'bg-gradient-to-br from-sky-400 to-violet-400'}`}>
                <Plus className={`w-4 h-4 ${editingEmployee ? 'text-amber-900' : 'text-sky-900'}`} />
              </span>
              {editingEmployee ? '编辑员工' : '添加员工'}
            </h3>
            <form onSubmit={handleSubmit} className="space-y-5">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">姓名 *</label>
                <input
                  type="text"
                  required
                  value={formData.employee_name}
                  onChange={(e) => setFormData({ ...formData, employee_name: e.target.value })}
                  className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                  placeholder="请输入员工姓名"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">部门</label>
                <input
                  type="text"
                  value={formData.department}
                  onChange={(e) => setFormData({ ...formData, department: e.target.value })}
                  className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                  placeholder="请输入部门名称"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">职位</label>
                <input
                  type="text"
                  value={formData.position}
                  onChange={(e) => setFormData({ ...formData, position: e.target.value })}
                  className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
                  placeholder="请输入职位名称"
                />
              </div>
              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="px-5 py-2.5 border border-slate-200 rounded-xl hover:bg-slate-50 transition-all font-medium text-slate-600"
                >
                  取消
                </button>
                <button
                  type="submit"
                  className="px-5 py-2.5 bg-gradient-to-r from-sky-400 to-violet-400 text-sky-900 rounded-xl hover:from-sky-500 hover:to-violet-500 transition-all font-medium shadow-sm hover:shadow-md border border-sky-400"
                >
                  保存
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}
